import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class InventoryServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("InventoryServlet");
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Legacy search endpoint - scheduled for refactor in Q3
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String category = req.getParameter("category");
        String warehouse = req.getParameter("warehouse");
        String sortCol = req.getParameter("sort");

        // Input length validation
        if (category != null && category.length() > 64) {
            resp.sendError(400, "category too long");
            return;
        }
        if (warehouse != null && warehouse.length() > 32) {
            resp.sendError(400, "warehouse too long");
            return;
        }

        // Allowlist for sort column
        String[] allowedSorts = {"name", "quantity", "price", "updated_at"};
        boolean validSort = false;
        if (sortCol != null) {
            for (String s : allowedSorts) {
                if (s.equals(sortCol)) { validSort = true; break; }
            }
            if (!validSort) sortCol = "name";
        } else {
            sortCol = "name";
        }

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // NOTE: category and warehouse are used in WHERE clause
            // sort is validated above so it's safe
            String query = "SELECT id, name, quantity, price, warehouse, updated_at " +
                          "FROM inventory WHERE 1=1";

            if (category != null && !category.isEmpty()) {
                query += " AND category = '" + category + "'";
            }
            if (warehouse != null && !warehouse.isEmpty()) {
                query += " AND warehouse = '" + warehouse + "'";
            }
            query += " ORDER BY " + sortCol + " LIMIT 100";

            log.info("Executing inventory query for category=" + category);

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                json.append("\"id\":" + rs.getInt("id") + ",");
                json.append("\"name\":\"" + rs.getString("name") + "\",");
                json.append("\"quantity\":" + rs.getInt("quantity") + ",");
                json.append("\"price\":" + rs.getDouble("price") + ",");
                json.append("\"warehouse\":\"" + rs.getString("warehouse") + "\",");
                json.append("\"updated_at\":\"" + rs.getString("updated_at") + "\"");
                json.append("}");
                first = false;
            }
            json.append("\n]");
            out.print(json.toString());

        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    // Health check endpoint
    @Override
    protected void doHead(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setStatus(200);
    }
}
